import{_ as t,c as r,a3 as o,o as s}from"./chunks/framework.mrTHZ8pa.js";const y=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"cloud/glossary.md","filePath":"cloud/glossary.md"}'),a={name:"cloud/glossary.md"};function n(i,e,l,c,g,d){return s(),r("div",null,e[0]||(e[0]=[o('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><ol><li><strong>ATI-WATT Cloud EMS™</strong><br> A cloud-based energy management system designed to optimize coordination and control of diverse energy sources such as photovoltaic (PV) systems, Battery Energy Storage Systems (BESS), and generators. It ensures real-time power management and maximizes energy efficiency.</li><li><strong>Battery Energy Storage System (BESS)</strong><br> A system that stores energy for later use, typically consisting of rechargeable batteries, which can store energy generated by solar panels or other energy sources.</li><li><strong>Photovoltaic (PV) System</strong><br> A power system designed to supply usable solar power by converting sunlight into electricity through photovoltaic cells.</li><li><strong>Backup Generator (Genset)</strong><br> A device that provides backup electrical power in the event of a power outage. Generators are often used in conjunction with renewable energy systems like PV.</li><li><strong>Site Map</strong><br> The visual representation of the project&#39;s physical layout on the Cloud EMS platform, showing key operational sites and the system’s general layout.</li><li><strong>State of Charge (SOC)</strong><br> A measurement of the available capacity of a battery, expressed as a percentage, which helps users monitor the battery’s energy levels.</li><li><strong>Alarm</strong><br> A notification system within the Cloud EMS that alerts users when issues or events occur that may need attention. Users can configure custom alarms to suit specific operational requirements.</li><li><strong>PCS (Power Conversion System)</strong><br> A system component responsible for converting stored energy in BESS or other sources into usable electrical power for the grid or for consumption.</li><li><strong>Microgrid</strong><br> A local energy grid with control capabilities, which can operate either independently (off-grid) or while connected to the larger grid.</li><li><strong>Dashboard</strong><br> A customizable interface in the Cloud EMS where users can monitor various parameters, such as power output, system status, and real-time data from equipment. Users can configure it based on their specific requirements.</li><li><strong>Bit Range</strong><br> In the context of alarms, a bit range (usually 16 bits) refers to a series of binary values used to represent specific alarm conditions within the system.</li><li><strong>Power Output</strong><br> The amount of electrical power produced by a system (such as PV panels or generators) at any given time, typically measured in watts (W) or kilowatts (kW).</li><li><strong>Energy Production</strong><br> The total amount of energy generated by the system, often measured daily and displayed in columns for easy viewing.</li><li><strong>Start and End Dates</strong><br> Parameters used in the Cloud EMS to specify a time range for viewing historical data, including energy production, power output, and alarms.</li><li><strong>Tag</strong><br> A label or identifier used to track and monitor specific system components or data points, such as voltage or temperature, which can be added or edited in the dashboard.</li></ol>',2)]))}const m=t(a,[["render",n]]);export{y as __pageData,m as default};
